from __future__ import annotations

import base64
import gzip
from pathlib import Path

PAYLOAD = """"""

target = Path("modules/01-duas-circunferencias/index.html")
target.parent.mkdir(parents=True, exist_ok=True)
target.write_bytes(gzip.decompress(base64.b64decode(PAYLOAD)))

index = Path("index.html")
text = index.read_text(encoding="utf-8")
text = text.replace(
    '<p class="eyebrow">Laboratório visual de intuição matemática</p>',
    '<p class="eyebrow">Branch experimental · reconstrução profunda</p>'
)
text = text.replace(
    '<p class="lead">A matemática entra pelos olhos, é interrogada pelas mãos e só então recebe fórmula.</p>',
    '<p class="lead">Aqui o laboratório deixa de ser resumo: o Lab 01 foi reconstruído como capítulo interativo longo, com nove cenas, caderno, exercícios e ataques às hipóteses. Os demais permanecem como referência curta enquanto não forem reescritos.</p>'
)
text = text.replace(
    '<article class="available"><a href="modules/01-duas-circunferencias/index.html"><small>LAB 01</small><h2>Duas circunferências</h2><p>Inferir a forma a partir da razão entre os raios.</p><span class="status">Abrir laboratório →</span></a></article>',
    '<article class="available"><a href="modules/01-duas-circunferencias/index.html"><small>LAB 01 · EDIÇÃO PROFUNDA</small><h2>Duas circunferências</h2><p>Nove cenas: construir, comparar casos, derivar, inverter, atacar hipóteses, exercitar e sintetizar.</p><span class="status">Abrir capítulo-modelo →</span></a></article>'
)
text = text.replace(
    '<p>Cinco laboratórios e um interlúdio disponíveis: previsão antes da manipulação, triângulo fundamental e fórmulas reveladas por último.</p>',
    '<p>Branch chatgpt-laboratorios-profundos: somente o Lab 01 foi reconstruído. Nada deste branch altera a main até aprovação explícita.</p>'
)
index.write_text(text, encoding="utf-8")

print(f"Lab profundo escrito em {target} ({target.stat().st_size} bytes).")
